import { readFileSync } from "node:fs";
import path from "node:path";
import type { ProfileInput } from "../src/profile/schema";

const dir = path.resolve(import.meta.dirname, "../../../fixtures");

/** Reads a file from the repo's fixtures/ folder (generated by `pnpm fixtures`). */
export function fixture(name: string): Uint8Array {
  return new Uint8Array(readFileSync(path.join(dir, name)));
}

